const res = $input.first().json;
const tree = res.tree || [];
const branch = $('Get Repo').first().json.default_branch;
const cfg = $('Config').first().json;
const repo = cfg.repo;
const sub = (cfg.subdir || '').replace(/\/$/, '');
const EXT = /\.(js|jsx|ts|tsx|vue|svelte|html|hbs|mjml|njk|ejs|json|svg)$/i;
const SKIP = /(^|\/)(node_modules|dist|build|\.next|coverage|__tests__|__mocks__|mocks?|fixtures|storybook|\.storybook|e2e|cypress|playwright)(\/|$)|\.(test|spec|stories)\.[jt]sx?$|\.d\.ts$|(package-lock|yarn\.lock|pnpm-lock)|(^|\/)package\.json$|(^|\/)tsconfig[^/]*$/i;
const isEn = p => /(^|\/)(en|en-US|en_US)(\.json|\/[^/]+\.json)$/.test(p);
let files = tree.filter(t => t.type === 'blob' && EXT.test(t.path) && !SKIP.test(t.path) && (t.size || 0) < 600000 && (!sub || t.path.startsWith(sub + '/')));
files = files.filter(t => !/\.json$/i.test(t.path) || isEn(t.path));
const total = files.length;
const capped = total > 1500;
files = files.slice(0, 1500);
if (!files.length) return [{ json: { skip: true, tree_truncated: !!res.truncated } }];
return files.map((f, i) => ({ json: { repo, branch, path: f.path, meta: i === 0 ? { total, capped, tree_truncated: !!res.truncated } : undefined } }));

/*
 * Static i18n scan of a repo. Read-only.
 *
 * Runs in two places with the same logic:
 *   1. n8n Code node ("Run Once for All Items"): paste the whole file; each input item is
 *      { json: { repo, path, content } }. The last lines return findings as items.
 *   2. Locally: node code_scan.js <dir> [repoName] > code_findings.json   (for an uploaded zip)
 *
 * Checks
 *   Hardcoded string   JSX/Vue/Svelte text nodes and user-facing attributes not wrapped in t()
 *   Hardcoded message  toast / alert / setError / validation messages with literal English
 *   Concatenation      t() joined with + or template literals (word order breaks)
 *   Hardcoded plural   count === 1 ? ... / "(s)" / pluralize()
 *   Locale formatting  toLocale*() with no locale or 'en-US', Intl.* with 'en', '$' + amount, US date masks
 *   Image with text    image referenced with no locale in its path (candidate — runtime OCR confirms)
 *   SVG with text      .svg asset containing <text> elements
 *   Missing key        t('key') used in code but absent from the en source file(s)
 *   Third-party        SDK / widget initialised with locale 'en' (Stripe, Nutrient, reCAPTCHA...)
 *   Language routing   absolute links in email templates with no locale
 */
const EXCLUDE = /(^|\/)(node_modules|dist|build|\.next|coverage|__tests__|__mocks__|mocks?|fixtures|storybook|e2e|cypress|playwright|scripts|migrations)(\/|$)|\.(test|spec|stories)\.[jt]sx?$|\.d\.ts$/i;
const CODE = /\.(jsx?|tsx?|vue|svelte|html|hbs|mjml|njk|ejs)$/i;
const EN_FILE = /(^|\/)(en|en-US|en_US)(\.json|\/[^/]+\.json)$/;

const stripComments = s => s
  .replace(/\/\*[\s\S]*?\*\//g, m => m.replace(/[^\n]/g, ' '))
  .replace(/(^|[^:\\'"`])\/\/[^\n]*/g, (m, p) => p + ' '.repeat(m.length - p.length))
  .replace(/<!--[\s\S]*?-->/g, m => m.replace(/[^\n]/g, ' '))
  .replace(/\{\/\*[\s\S]*?\*\/\}/g, m => m.replace(/[^\n]/g, ' '));

const lineOf = (s, i) => s.slice(0, i).split('\n').length;
const words = t => (t.match(/[A-Za-z]{2,}/g) || []);
const looksCopy = t => {
  t = t.trim();
  if (!t || /^[\W\d_]+$/.test(t)) return false;
  if (/^(https?:|mailto:|tel:|\/|#|\.|[a-z]+[A-Z]\w*$|[A-Z0-9_]+$|[a-z0-9-]+$)/.test(t)) return false; // urls, paths, identifiers, CONSTS, kebab
  if (/[{}();=<>]|=>|&&|\|\|/.test(t)) return false;           // code, not copy
  const w = words(t);
  return w.length >= 2 || (w.length === 1 && w[0].length >= 4 && /^[A-Z][a-z]+$/.test(w[0]));
};

function flatten(obj, pre = '', out = new Set()) {
  if (obj && typeof obj === 'object' && !Array.isArray(obj)) {
    for (const [k, v] of Object.entries(obj)) {
      const key = pre ? pre + '.' + k : k;
      if (v && typeof v === 'object' && !Array.isArray(v) && !('one' in v || 'other' in v)) flatten(v, key, out);
      else out.add(key);
    }
  }
  return out;
}

function scan(files, dnt = []) {
  const findings = [];
  const add = (f, i, check, severity, found, fix, s) =>
    findings.push({ check, severity, repo: f.repo, file: f.path, line: s ? lineOf(s, i) : null, found: String(found).trim().slice(0, 220), fix });
  const dntRe = dnt.length ? new RegExp(dnt.map(t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|'), 'gi') : null;
  const notDnt = t => !dntRe || looksCopy(t.replace(dntRe, ' '));

  // English source keys
  const enKeys = new Set();
  for (const f of files) if (EN_FILE.test(f.path)) {
    try {
      const ns = (f.path.match(/(?:^|\/)en\/([^/]+)\.json$/) || [])[1];
      for (const k of flatten(JSON.parse(f.content))) { enKeys.add(k); if (ns) enKeys.add(ns + '.' + k); }
    } catch (e) { findings.push({ check: 'Scan note', severity: 'Low', repo: f.repo, file: f.path, line: null, found: 'Could not parse English source file', fix: '' }); }
  }

  for (const f of files) {
    if (EXCLUDE.test(f.path)) continue;
    if (/\.svg$/i.test(f.path)) {
      const m = f.content.match(/<text[^>]*>([\s\S]*?)<\/text>/gi);
      if (m) {
        const txt = m.map(x => x.replace(/<[^>]+>/g, '')).join(' ').replace(/\s+/g, ' ');
        if (words(txt).length >= 2) add(f, 0, 'Unlocalized images', 'High', `SVG contains live text: "${txt.slice(0, 120)}"`, 'Move the text out of the SVG into a translatable string, or provide per-locale SVGs');
      }
      continue;
    }
    if (!CODE.test(f.path)) continue;
    const s = stripComments(f.content);
    const isMarkup = /\.(jsx|tsx|vue|svelte|html|hbs|mjml|njk|ejs)$/i.test(f.path) || /return\s*\(\s*</.test(s);
    let m;

    if (isMarkup) {
      // text between tags
      const reText = />\s*([^<>{}`]*?[A-Za-z][^<>{}`]*?)\s*</g;
      while ((m = reText.exec(s))) {
        const t = m[1].replace(/&nbsp;|&amp;|&[a-z]+;/g, ' ').trim();
        const before = s.slice(Math.max(0, m.index - 40), m.index);
        if (/(\bstyle|\bscript|=\s*$)/i.test(before)) continue;
        if (looksCopy(t) && notDnt(t)) add(f, m.index, 'Hardcoded string', 'High', t, 'Extract to a key and render with t()', s);
      }
      // text inside {'…'} or {"…"} in JSX
      const reBraced = /\{\s*(['"])([^'"\n]{3,})\1\s*\}/g;
      while ((m = reBraced.exec(s))) if (looksCopy(m[2]) && notDnt(m[2])) add(f, m.index, 'Hardcoded string', 'High', m[2], 'Extract to a key and render with t()', s);
      // user-facing attributes
      const reAttr = /\b(placeholder|title|alt|aria-label|label|tooltip|helperText|errorMessage|emptyText|description|heading|buttonText|cta)\s*=\s*(['"])([^'"\n]*[A-Za-z]{2,}[^'"\n]*)\2/g;
      while ((m = reAttr.exec(s))) if (looksCopy(m[3]) && notDnt(m[3]))
        add(f, m.index, 'Hardcoded string', m[1] === 'alt' || m[1] === 'aria-label' ? 'Medium' : 'High', `${m[1]}="${m[3]}"`, 'Pass t() into the attribute', s);
    }
    // messages built in logic
    const reMsg = /\b(toast(?:\.\w+)?|alert|confirm|notify(?:\w*)|setError|setMessage|showError|enqueueSnackbar|message\s*:|error\s*:|title\s*:|label\s*:|placeholder\s*:|description\s*:|yup\.\w+\(\)\.\w+\(|\.(?:required|min|max|email|matches)\([^)]*?,?)\s*\(?\s*(['"`])([^'"`\n]*[A-Za-z]{3,}\s[^'"`\n]*)\2/g;
    while ((m = reMsg.exec(s))) if (looksCopy(m[3]) && notDnt(m[3]))
      add(f, m.index, 'Hardcoded string', 'High', `${m[1].trim()} "${m[3]}"`, 'User-visible message: move to a key', s);
    const reThrow = /throw new Error\(\s*(['"`])([^'"`\n]*[A-Za-z]{3,}\s[^'"`\n]*)\1/g;
    while ((m = reThrow.exec(s))) add(f, m.index, 'Hardcoded string', 'Low', `throw new Error("${m[2]}")`, 'Only a finding if this message reaches the UI', s);

    // concatenation around t()
    const reCat = /(\bt\([^()]*\)\s*\+\s*(?!\s*\d)|\+\s*\bt\([^()]*\)|`[^`]*\$\{\s*t\([^`]*\}[^`]*[A-Za-z]{2,}[^`]*`|`[^`]*[A-Za-z]{2,}[^`]*\$\{\s*t\()/g;
    while ((m = reCat.exec(s))) add(f, m.index, 'Concatenation', 'High', m[0].slice(0, 160), 'Use one key with a placeholder so translators control word order', s);
    // plurals
    const rePl = /(===?\s*1\s*\?\s*['"`t]|>\s*1\s*\?\s*['"`t]|\(s\)['"`]|\bpluralize\(|\+\s*['"]s['"])/g;
    while ((m = rePl.exec(s))) add(f, m.index, 'Hardcoded plural', 'High', s.split('\n')[lineOf(s, m.index) - 1].trim(), 'Use an ICU/i18next plural key (one/few/many/other)', s);
    // locale formatting
    const reFmt = /(\.toLocale(?:Date|Time)?String\(\s*\)|\.toLocale(?:Date|Time)?String\(\s*['"]en(?:-US)?['"]|Intl\.(?:NumberFormat|DateTimeFormat|RelativeTimeFormat|PluralRules)\(\s*['"]en(?:-US)?['"]|['"`]\$['"`]\s*\+|\$\{[^}]*\}\s*(?:USD|EUR)\b|['"`](?:MM\/DD\/YYYY|MM\/dd\/yyyy|MMM D, YYYY|MMM d, yyyy)['"`]|\bmoment\([^)]*\)\.format\(\s*['"][^'"]*['"]\s*\))/g;
    while ((m = reFmt.exec(s))) add(f, m.index, 'Locale formatting', 'Medium', m[0], 'Format with the active locale (Intl.* with the current locale)', s);
    // images referenced without a locale segment
    const reImg = /(['"`(])([^'"`()\s]*\.(?:png|jpe?g|webp|gif|avif))(['"`)])/gi;
    while ((m = reImg.exec(s))) {
      const pth = m[2];
      if (/(\$\{|\{locale|\{lang|\/(en|de|fr|es|it|pt|nl|pl)\/|[_-](en|de|fr)\.|icon|logo|flag|avatar|favicon)/i.test(pth)) continue;
      if (/(banner|hero|promo|cta|step|how-?it|mock|screen|badge|feature|onboarding|tutorial|illustration)/i.test(pth))
        add(f, m.index, 'Unlocalized images', 'Medium', pth, 'Candidate: check the image for baked-in text (runtime OCR confirms)', s);
    }
    // third-party SDKs initialised in English
    const reTp = /\b(locale|lang|language|hl)\s*[:=]\s*['"]en(?:-US|_US|-GB)?['"]/g;
    while ((m = reTp.exec(s))) {
      const ctx = s.slice(Math.max(0, m.index - 200), m.index + 60);
      if (/defaultLocale|fallbackLng|fallbackLocale|sourceLocale|baseLocale|defaultLanguage/.test(ctx.slice(-120, -40 + 120))) continue;
      add(f, m.index, 'Third-party widgets', /stripe|elements|paypal|nutrient|pspdfkit|intercom|recaptcha|calendly|google/i.test(ctx) ? 'High' : 'Medium',
          ctx.split('\n').find(l => l.includes(m[0])).trim().slice(0, 160), 'Pass the active locale instead of a fixed English one', s);
    }
    if (isMarkup) {
      // numbers, symbols and units glued to expressions: 50%, /month, 4.6 — should be keys or Intl
      const reSym = /(\}\s*(%|\/\s*(mo|month|year|yr|week)\b|(h|m|min|sec|MB|GB|KB)\b)|>\s*\d+(\.\d+)?\s*(%|MB|GB|★)\s*<|>\s*(\/\s*(month|year|mo)|per (month|year))\s*<)/g;
      while ((m = reSym.exec(s))) add(f, m.index, 'Locale formatting', 'Medium', s.split('\n')[lineOf(s, m.index) - 1].trim().slice(0, 160),
          'Units, percentages and "/month" belong in the key or in Intl.NumberFormat — they move and change by locale', s);
      // links in email templates without a locale
      if (/\.(hbs|mjml|njk|ejs|html)$/i.test(f.path) || /(^|\/)(emails?|mail|templates?)\//i.test(f.path)) {
        const reHref = /href\s*=\s*["'](https?:\/\/[^"'{}$]+)["']/g;
        while ((m = reHref.exec(s))) if (!/(unsubscribe|facebook|instagram|twitter|linkedin|apple\.com|google\.com|x\.com)/i.test(m[1]))
          add(f, m.index, 'Language routing', 'Medium', m[1], 'Email link has no locale: localized users land on the English page', s);
      }
    }
    // hardcoded English lists (months, weekdays, countries)
    const reList = /\[\s*(['"])(January|Jan|Monday|Mon|Afghanistan|Albania|Argentina|Australia|Austria)\1\s*,\s*(['"])[A-Z][a-z]+\3/g;
    while ((m = reList.exec(s))) add(f, m.index, 'Locale formatting', 'High', s.slice(m.index, m.index + 80).replace(/\s+/g, ' '),
        'Hardcoded English month/day/country list: use Intl.DateTimeFormat / Intl.DisplayNames', s);

    // keys used in code
    if (enKeys.size) {
      const nsM = s.match(/use(?:Translations?|Translation)\(\s*['"]([\w.-]+)['"]/);
      const ns = nsM ? nsM[1] : '';
      const reKey = /\bt\(\s*['"]([\w.-]+(?:[.:][\w.-]+)+|[\w-]{3,})['"]/g;
      while ((m = reKey.exec(s))) {
        const k = m[1].replace(':', '.');
        if (enKeys.has(k) || (ns && enKeys.has(ns + '.' + k))) continue;
        if ([...enKeys].some(e => e.endsWith('.' + k))) continue;
        add(f, m.index, 'Missing key', 'High', ns ? `${ns} → ${k}` : k, 'Key is used in code but not in the English source: it will render raw or fall back', s);
      }
    }
  }
  const counts = {};
  for (const x of findings) counts[x.check] = (counts[x.check] || 0) + 1;
  return { en_keys: enKeys.size, files_scanned: files.filter(f => !EXCLUDE.test(f.path) && (CODE.test(f.path) || /\.svg$/i.test(f.path))).length, counts, findings };
}

// ---- entry points ----
if (typeof $input !== 'undefined') {
  // n8n Code node
  const items = $input.all().map(i => i.json).filter(j => j && j.path && typeof j.content === 'string');
  const dnt = (items[0] && items[0].dnt) || [];
  const r = scan(items, dnt);
  return [{ json: { en_keys: r.en_keys, files_scanned: r.files_scanned, counts: r.counts, findings: r.findings.slice(0, 3000), truncated: r.findings.length > 3000 } }];
} else if (typeof require !== 'undefined' && require.main === module) {
  const fs = require('fs'), path = require('path');
  const root = process.argv[2], repo = process.argv[3] || path.basename(root);
  const dnt = (process.argv[4] || '').split(',').filter(Boolean);
  const files = [];
  (function walk(d) {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name), rel = path.relative(root, p).split(path.sep).join('/');
      if (e.isDirectory()) { if (!/^(node_modules|\.git|dist|build|\.next)$/.test(e.name)) walk(p); }
      else if (/\.(jsx?|tsx?|vue|svelte|html|hbs|mjml|njk|ejs|json|svg)$/i.test(e.name) && fs.statSync(p).size < 600000)
        files.push({ repo, path: rel, content: fs.readFileSync(p, 'utf8') });
    }
  })(root);
  process.stdout.write(JSON.stringify(scan(files, dnt), null, 1));
}
if (typeof module !== 'undefined') module.exports = { scan };

const src = $('Loop Files').itemMatching($itemIndex).json;
const c = $json.data;
if (src.skip) return { json: { skip: true } };
return { json: { repo: src.repo, path: src.path, content: typeof c === 'string' ? c : (c == null ? null : JSON.stringify(c)), dnt: $('Config').first().json.dnt } };
